// ASTRA V4 Historical Data Bridge
// Reads the compact daily history index generated by the post-market refresh.
// Falls back to the canonical legacy repository if the local cache is absent.

const fs = require('fs');
const path = require('path');
const { getEGXSymbols, getRegistryMeta } = require('../registry/egx-symbol-registry');
const { loadRemoteAtomicPair } = require('../atomic-remote-store');

const LEGACY_REPO =
  'https://raw.githubusercontent.com/rasheadsca-star/RAS-EGX-PRO2026-NEXT/main/data/history';

const LOCAL_INDEX_PATH =
  path.join(__dirname, '..', '..', 'data', 'history-index.json');

const WATCHLIST = getEGXSymbols();
const CACHE = new Map();
let LOCAL_INDEX_CACHE = null;
let LOCAL_INDEX_LOADED = false;

const REQUEST_TIMEOUT_MS = 8000;
const BATCH_SIZE = 50;

function getLocalHistoryIndex() {
  if (LOCAL_INDEX_LOADED) return LOCAL_INDEX_CACHE;

  LOCAL_INDEX_LOADED = true;

  try {
    if (!fs.existsSync(LOCAL_INDEX_PATH)) return null;
    LOCAL_INDEX_CACHE = JSON.parse(
      fs.readFileSync(LOCAL_INDEX_PATH, 'utf8')
    );
    return LOCAL_INDEX_CACHE;
  } catch (error) {
    console.log('ASTRA LOCAL HISTORY INDEX ERROR', error?.message || error);
    LOCAL_INDEX_CACHE = null;
    return null;
  }
}

function loadLocalHistory(symbol) {
  try {
    const index = getLocalHistoryIndex();
    const entry = index?.symbols?.[symbol];

    if (!entry || !Array.isArray(entry.sessions)) return null;

    return entry.sessions
      .map((row) => ({
        date: row.date,
        open: Number(row.open || 0),
        high: Number(row.high || 0),
        low: Number(row.low || 0),
        close: Number(row.close || 0),
        volume: Number(row.volume || 0),
        source: row.source || entry.primarySource || 'canonical-history'
      }))
      .filter((row) => row.date && row.close > 0)
      .sort((a, b) => a.date.localeCompare(b.date));
  } catch (error) {
    console.log('ASTRA LOCAL HISTORY SYMBOL ERROR', symbol, error?.message || error);
    return null;
  }
}

async function fetchRemoteHistory(symbol) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const url = `${LEGACY_REPO}/${symbol}.json`;

    const response = await fetch(url, {
      headers: { 'User-Agent': 'ASTRA-V4/4.0' },
      signal: controller.signal
    });

    if (!response.ok) {
      console.log('ASTRA HISTORY FETCH FAILED', symbol, response.status);
      return [];
    }

    const payload = await response.json();
    const rows = Array.isArray(payload?.sessions) ? payload.sessions : [];

    return rows
      .map((row) => ({
        date: row.date,
        open: Number(row.open || 0),
        high: Number(row.high || 0),
        low: Number(row.low || 0),
        close: Number(row.close || 0),
        volume: Number(row.volume || 0),
        source:
          row.primarySource ||
          payload.primarySource ||
          'legacy-history'
      }))
      .filter((row) => row.date && row.close > 0)
      .sort((a, b) => a.date.localeCompare(b.date));
  } catch (error) {
    console.log(
      'ASTRA HISTORY ERROR',
      symbol,
      error?.message || 'unknown'
    );
    return [];
  } finally {
    clearTimeout(timeout);
  }
}

async function fetchHistory(symbol) {
  if (CACHE.has(symbol)) {
    return CACHE.get(symbol);
  }

  const local = loadLocalHistory(symbol);

  if (Array.isArray(local) && local.length) {
    CACHE.set(symbol, local);
    return local;
  }

  const remote = await fetchRemoteHistory(symbol);
  CACHE.set(symbol, remote);
  return remote;
}

function latestSession(rows = []) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => row?.date || null)
    .filter(Boolean)
    .sort()
    .at(-1) || null;
}

async function shouldBypassStaleAtomic(remoteAtomic, requested = []) {
  if (remoteAtomic?.available !== true || !remoteAtomic.expectedSession) return false;

  const probeSymbols = requested.slice(0, Math.min(12, requested.length));
  if (!probeSymbols.length) return false;

  const probes = await Promise.all(
    probeSymbols.map(async (symbol) => {
      const rows = await fetchRemoteHistory(symbol);
      return { symbol, latestSession: latestSession(rows), rows };
    })
  );

  const freshestDirectSession = probes
    .map((item) => item.latestSession)
    .filter(Boolean)
    .sort()
    .at(-1) || null;

  const bypass = Boolean(
    freshestDirectSession &&
    freshestDirectSession > remoteAtomic.expectedSession
  );

  if (bypass) {
    console.log(
      'ASTRA STALE ATOMIC BYPASS',
      JSON.stringify({
        atomicSession: remoteAtomic.expectedSession,
        freshestDirectSession,
        probedSymbols: probes.length
      })
    );
    for (const probe of probes) {
      if (probe.rows?.length) CACHE.set(probe.symbol, probe.rows);
    }
  }

  return bypass;
}

function rowsFromIndex(index = {}, symbol) {
  const entry = index?.symbols?.[symbol];
  if (!entry || !Array.isArray(entry.sessions)) return [];
  return entry.sessions
    .map((row) => ({
      date: row.date,
      open: Number(row.open || 0),
      high: Number(row.high || 0),
      low: Number(row.low || 0),
      close: Number(row.close || 0),
      volume: Number(row.volume || 0),
      source: row.source || entry.primarySource || 'canonical-history'
    }))
    .filter((row) => row.date && row.close > 0)
    .sort((a, b) => a.date.localeCompare(b.date));
}

async function loadLegacyHistory(symbols = WATCHLIST) {
  const requested = Array.from(
    new Set(
      Array.isArray(symbols) && symbols.length
        ? symbols
        : WATCHLIST
    )
  );

  const remoteAtomic = await loadRemoteAtomicPair();
  const entries = [];
  const bypassStaleAtomic = await shouldBypassStaleAtomic(remoteAtomic, requested);

  if (remoteAtomic.available === true && bypassStaleAtomic !== true) {
    for (const symbol of requested) {
      entries.push([symbol, rowsFromIndex(remoteAtomic.history, symbol)]);
    }
  } else {
    for (let offset = 0; offset < requested.length; offset += BATCH_SIZE) {
      const batch = requested.slice(offset, offset + BATCH_SIZE);

      const batchEntries = await Promise.all(
        batch.map(async (symbol) => [
          symbol,
          await fetchHistory(symbol)
        ])
      );

      entries.push(...batchEntries);
    }
  }

  const loaded = entries.filter(([, data]) => data.length > 0).length;

  console.log(
    'ASTRA HISTORY SCAN',
    JSON.stringify({
      ...getRegistryMeta(),
      requestedSymbols: requested.length,
      loadedSymbols: loaded,
      failedSymbols: requested.length - loaded,
      localIndex: fs.existsSync(LOCAL_INDEX_PATH),
      runtimeHistorySource:
        remoteAtomic.available === true && bypassStaleAtomic !== true
          ? 'REMOTE_ATOMIC_GITHUB'
          : bypassStaleAtomic === true
            ? 'DIRECT_LEGACY_FRESHNESS_BYPASS'
            : 'LOCAL_OR_LEGACY_FALLBACK',
      remoteAtomicSession: remoteAtomic.available === true ? remoteAtomic.expectedSession : null,
      staleAtomicBypassed: bypassStaleAtomic === true,
      remoteAtomicFingerprint: remoteAtomic.available === true ? remoteAtomic.sourceSessionDataHash : null,
      batchSize: BATCH_SIZE
    })
  );

  return Object.fromEntries(entries);
}

module.exports = {
  WATCHLIST,
  BATCH_SIZE,
  loadLegacyHistory,
  fetchHistory,
  getRegistryMeta,
  latestSession,
  shouldBypassStaleAtomic,
  rowsFromIndex
};
